package com.alex.universalrangedweaponapi.api; import net.minecraft.core.registries.Registries; import net.minecraft.resources.Identifier; import net.minecraft.tags.TagKey; import net.minecraft.world.item.Item; import net.minecraft.world.item.ItemStack; import java.util.*; import java.util.concurrent.*; public final class UniversalRangedWeaponApi { public static final TagKey<Item> RANGED_WEAPONS=TagKey.create(Registries.ITEM,Identifier.fromNamespaceAndPath("universal-ranged-weapon-api","ranged_weapons")); private static final Set<Item> ITEMS=ConcurrentHashMap.newKeySet(); private static final List<RangedWeaponHandler> HANDLERS=new CopyOnWriteArrayList<>(); private static final Map<RangedWeaponHookType,List<RangedWeaponHook>> HOOKS=new EnumMap<>(RangedWeaponHookType.class); static{for(var t:RangedWeaponHookType.values())HOOKS.put(t,new CopyOnWriteArrayList<>());} private UniversalRangedWeaponApi(){} public static void registerWeapon(Item i){ITEMS.add(Objects.requireNonNull(i));} public static boolean unregisterWeapon(Item i){return ITEMS.remove(i);} public static boolean isRangedWeapon(ItemStack s){return s.is(RANGED_WEAPONS)||ITEMS.contains(s.getItem());} public static Set<Item> registeredItems(){return Set.copyOf(ITEMS);} public static void registerHandler(RangedWeaponHandler h){HANDLERS.add(Objects.requireNonNull(h));} public static boolean unregisterHandler(RangedWeaponHandler h){return HANDLERS.remove(h);} public static void registerHook(RangedWeaponHookType t,RangedWeaponHook h){HOOKS.get(t).add(Objects.requireNonNull(h));} public static boolean unregisterHook(RangedWeaponHookType t,RangedWeaponHook h){return HOOKS.get(t).remove(h);} public static RangedWeaponActionResult fireHook(RangedWeaponHookType t,RangedWeaponContext c,RangedWeaponActionResult r){for(var h:HOOKS.get(t)){r=h.apply(c,r);if(r==RangedWeaponActionResult.FAIL)break;}return r;} public static RangedWeaponActionResult invoke(RangedWeaponContext c){var r=fireHook(RangedWeaponHookType.BEFORE_HANDLER,c,RangedWeaponActionResult.PASS);if(r!=RangedWeaponActionResult.PASS)return r;for(var h:HANDLERS){r=h.handle(c);if(r!=RangedWeaponActionResult.PASS)break;}return fireHook(RangedWeaponHookType.AFTER_HANDLER,c,r);} }